from pathlib import Path
import base64

# Exact Driver/Mech AI logo supplied by the user.
# Build-time embedding guarantees the logo is actually packaged in the APK.
LOGO_B64 = """"""

logo = base64.b64decode(LOGO_B64)
main = Path("app/src/main")
(main / "assets").mkdir(parents=True, exist_ok=True)
(main / "res" / "drawable").mkdir(parents=True, exist_ok=True)
(main / "assets" / "driver_mech_logo.jpg").write_bytes(logo)
(main / "res" / "drawable" / "logo_exact.jpg").write_bytes(logo)

# Make the login image URL explicit and prevent DRIVER ID from overlapping the mobile placeholder.
js = main / "assets" / "app_shell.js"
if js.exists():
    s = js.read_text(encoding="utf-8")
    s = s.replace('src="driver_mech_logo.jpg"', 'src="file:///android_asset/driver_mech_logo.jpg"')
    s = s.replace('padding:8px 48px 8px 48px;font-size:18px', 'padding:8px 112px 8px 48px;font-size:18px')
    js.write_text(s, encoding="utf-8")

print(f"Exact Driver/Mech AI logo installed: {len(logo)} bytes")
